"""Reference-based packaging screen only; does not modify cycle mass or payoff."""
from pathlib import Path
import json,math


def main():
 root=Path(__file__).resolve().parents[2];rows=[]
 refs=json.loads((root/'modeling/deployment/reference_data.json').read_text())
 qv=refs['solar'][0]['stowed_kW_m3']
 for label in ('apogee_937','joint_boundary'):
  r=json.loads((root/f'results/altitude_sensitivity/limited_reference/{label}.json').read_text());o=r['outputs'];d=r['inputs']['design']
  area=math.pi*d['front_diameter_m']**2/4
  whole=area*o['overall_length_allowance_m'] # generous straight inner cylinder, before heads/structure
  tank=o['rear_geometry']['volume_m3'];power=o['solar_MW']*1000
  rows.append(dict(case=label,solar_kW=power,source_stowed_kW_m3=qv,array_reference_envelope_m3=power/qv,
   entire_inner_cylinder_upper_m3=whole,rear_gas_m3=tank,upper_non_tank_space_m3=whole-tank,
   array_equivalent_full_bore_length_m=power/qv/area,
   array_alone_required_kW_m3=power/(whole-tank),
   front_metal_material_m3=o['masses_kg']['hot_metal']/r['inputs']['performance']['metal_density_kg_m3'],
   compressor_row_lengths_sum_m=sum(b['bank_length_m'] for b in o['compressor_analysis']['dive']['banks']),
   note='Mission bus power equated to reference rated power; external packaging overhead omitted. No feasibility certification.'))
 battery=[]
 for ref in refs['battery']:
  name,E,dim=ref['name'],ref['energy_Wh'],ref['dimensions_mm']
  litres=math.prod(dim)/1e6;battery.append(dict(name=name,dimensions_mm=dim,energy_Wh=E,box_L=litres,Wh_L=E/litres))
 dest=root/'results/packing_research';dest.mkdir(exist_ok=True)
 (dest/'screen.json').write_text(json.dumps(dict(status='Reference packaging comparison, not integrated vehicle model',solar_cases=rows,battery_envelopes=battery),indent=2)+'\n')
 lines=['# First close-pass packing screen','',
 'Generated by `.venv/bin/python -m atmo_scoops.studies.packing_screen`. This checks saved numerical load cases against a named reference packaging figure; it is not a new payoff run or an optimizer capability. See [source evidence](../solar/PACKAGING.md).','',
 '| Saved case | Required solar power (GW) | Array envelope at 40 kW/m³ | Whole inner-cylinder upper volume | Rear gas volume | Full-bore array-equivalent depth |','|---|---:|---:|---:|---:|---:|']
 for x in rows:lines.append(f"| {x['case']} | {x['solar_kW']/1e6:.3f} | {x['array_reference_envelope_m3']:,.0f} m³ | {x['entire_inner_cylinder_upper_m3']:,.0f} m³ | {x['rear_gas_m3']:,.0f} m³ | {x['array_equivalent_full_bore_length_m']:,.1f} m |")
 lines+=['','The cylinder is deliberately generous: no head/wall/rib losses are subtracted. Mission bus power is equated to source rated power and no repeat-cycle mechanism, protective bay or external clearance is added. A real rated-power mapping may demand more array. The reference 40 kW/m³ is a published design figure, not a fundamental maximum for future technology.','',
 'For the 937 km-apogee case, reference array packaging alone exceeds the entire hull. For the deeper joint-boundary case, arrays plus retained warm-gas volume already exceed the hull. This invalidates claiming that either saved case fits using this reference packaging. It does not establish infeasibility for every future technology, power system or collection policy.','',
 '| Saved case | Non-tank volume upper bound | Array packing needed if it occupied ALL that space | Front metal material alone | Computed blade-row lengths |','|---|---:|---:|---:|---:|']
 for x in rows:lines.append(f"| {x['case']} | {x['upper_non_tank_space_m3']:,.0f} m³ | {x['array_alone_required_kW_m3']:.1f} kW/m³ | {x['front_metal_material_m3']:,.0f} m³ | {x['compressor_row_lengths_sum_m']:.2f} m |")
 lines+=['','The required packing numbers leave **no room** for any other hardware or front/interstage gas. They are demand thresholds for this load/layout, not proposed technology coefficients. Metal material volume excludes rack gas passages, frames and deployment hardware. Blade-row length excludes cooler chambers, buffers and drives; it does not justify the previous 100 m bay or prove that a 22 m bay suffices.','',
 'Battery envelope cross-checks (manufacturer dimensions, not installed bays):','',
 '| Module | Bounding volume | Nameplate energy / volume |','|---|---:|---:|']
 for b in battery:lines.append(f"| {b['name']} | {b['box_L']:.3f} L | {b['Wh_L']:.1f} Wh/L |")
 lines+=['','No battery or radiator volume is silently set to zero in a complete budget: those contributions remain to be resolved. Full input/result values for this partial check are in [screen.json](../../results/packing_research/screen.json). The source module boundary and duty limitations are described in the [electrical dossier](../electrical/PACKAGING.md).','']
 (root/'modeling/deployment/PACKING_SCREEN.md').write_text('\n'.join(lines))

if __name__=='__main__':main()
